usage:
@State private var volume = 64.0

Slider(value: $volume, in: 0...100, step: 1) {
    Text("Volume")
} minimumValueLabel: {
    Image(systemName: "speaker.fill")
        .accessibilityHidden(true)
} maximumValueLabel: {
    Image(systemName: "speaker.wave.3.fill")
        .accessibilityHidden(true)
}
.controlSize(.large)
